@app.function(hide_code=True)
def dot_rows(rows, lo, hi, ticks, fmt, marks, legend=None, note=None, caption=""):
    """One row per model. `marks` maps a value key to (fill, stroke) for each dot drawn on the row;
    `legend` names those keys beside the first row's dots, `note` (header, fn) adds a right-hand column."""
    left, track, right, pitch = 130, 400, 110 if note else 30, 26
    top = 26 if legend or note else 0
    height = top + len(rows) * pitch + (44 if caption else 28)
    axis = top + len(rows) * pitch + 2
    x = lambda v: left + (v - lo) / (hi - lo) * track
    parts = [f'<line x1="{x(t)}" x2="{x(t)}" y1="{top + 6}" y2="{axis}" stroke="{RULE}"/>'
             + text(x(t), axis + 12, fmt(t), "middle", MUTED, 11, True) for t in ticks]
    if caption:
        parts.append(text(left, axis + 30, caption, "start", MUTED, 11))
    if note:
        parts.append(text(left + track + 24, 12, note[0], "start", MUTED, 11))
    if legend:
        first = sorted(rows[0][1].items(), key=lambda kv: kv[1])
        for k, (key, v) in enumerate(first):
            parts.append(text(x(v) + (-10 if k == 0 else 10), 12, legend[key], "end" if k == 0 else "start", MUTED, 11))
    for i, (m, values) in enumerate(rows):
        y = top + 14 + i * pitch
        xs = [x(v) for v in values.values()]
        parts.append(f'<g class="m">{text(left - 14, y, LABEL[m], "end")}'
                     f'<line x1="{min(xs)}" x2="{max(xs)}" y1="{y}" y2="{y}" stroke="{COLOR[m]}" stroke-width="2"/>')
        for key, v in values.items():
            fill, stroke = marks[key]
            parts.append(f'<circle cx="{x(v)}" cy="{y}" r="5.5" fill="{fill or COLOR[m]}" stroke="{stroke or COLOR[m]}"'
                         f' stroke-width="2"><title>{LABEL[m]}: {fmt(v)}</title></circle>')
        if note:
            parts.append(text(left + track + 24, y, note[1](m), "start", MUTED, 11, True))
        parts.append("</g>")
    return svg(left + track + right, height, "".join(parts), "rows")


