@app.function(hide_code=True)
def judge_matrix():
    mat = D["e1"]["matrix"]
    hi = max(mat[g][j] for g in ORDER for j in ORDER)
    left, top, cell = 130, 100, 44
    right = left + len(ORDER) * cell
    parts = [text(left - 14, top - 14, "made by ↓  judged by →", "end", MUTED, 11)]
    for j, m in enumerate(ORDER):
        cx = left + j * cell + cell / 2
        parts.append(f'<rect x="{cx - cell / 2 + 1}" y="{top - 6}" width="{cell - 2}" height="3" rx="1.5" fill="{COLOR[m]}"/>'
                     + text(cx, top - 14, LABEL[m], "start", MUTED, 11, extra=f'transform="rotate(-40 {cx:.1f} {top - 14})"'))
    for i, g in enumerate(ORDER):
        y = top + i * cell
        row = [text(left - 14, y + cell / 2, LABEL[g], "end")]
        for j, m in enumerate(ORDER):
            v = mat[g][m]
            own = ' stroke="currentColor" stroke-width="1.5"' if g == m else ""
            row.append(f'<rect x="{left + j * cell + 1}" y="{y + 1}" width="{cell - 2}" height="{cell - 2}" rx="2" fill="#E89A39"'
                       f' fill-opacity="{math.sqrt(max(0, v) / hi) * 0.85:.3f}"{own}>'
                       f'<title>{LABEL[g]}\'s images, judged by {LABEL[m]}: {v:+.2f}</title></rect>'
                       + text(left + j * cell + cell / 2, y + cell / 2, f"{v:.1f}", "middle", size=11, mono=True,
                              extra='pointer-events="none"'))
        parts.append(f'<g class="m">{"".join(row)}</g>')
    bottom = top + len(ORDER) * cell
    parts.append(text(left, bottom + 18, "SDs above unsteered, averaged over the four regions", "start", MUTED, 11))
    return svg(right + 40, bottom + 30, "".join(parts))


@app.cell(hide_code=True)
def _():
    judge_matrix()
    return


